SELECT CAST(SUM(IIF(customers."货币类型" = 'EUR', 1, 0)) AS REAL) / SUM(IIF(customers."货币类型" = 'CZK', 1, 0)) AS ratio FROM "客户" AS customers	debit_card_specializing
SELECT AVG(t2."消费量") / 12 AS _col_0 FROM "客户" AS t1 INNER JOIN "年月消费" AS t2 ON t1."客户编号" = t2."客户编号" WHERE SUBSTRING(t2."日期", 1, 4) = '2013' AND t1."客户群组" = 'SME'	debit_card_specializing
SELECT SUM(IIF(t1."货币类型" = 'CZK', t2."消费量", 0)) - SUM(IIF(t1."货币类型" = 'EUR', t2."消费量", 0)) AS _col_0 FROM "客户" AS t1 INNER JOIN "年月消费" AS t2 ON t1."客户编号" = t2."客户编号" WHERE SUBSTRING(t2."日期", 1, 4) = '2012'	debit_card_specializing
SELECT CAST(SUM(IIF(t1."客户群组" = 'SME', t2."消费量", 0)) AS REAL) / COUNT(t1."客户编号") - CAST(SUM(IIF(t1."客户群组" = 'LAM', t2."消费量", 0)) AS REAL) / COUNT(t1."客户编号") AS _col_0, CAST(SUM(IIF(t1."客户群组" = 'LAM', t2."消费量", 0)) AS REAL) / COUNT(t1."客户编号") - CAST(SUM(IIF(t1."客户群组" = 'KAM', t2."消费量", 0)) AS REAL) / COUNT(t1."客户编号") AS _col_1, CAST(SUM(IIF(t1."客户群组" = 'KAM', t2."消费量", 0)) AS REAL) / COUNT(t1."客户编号") - CAST(SUM(IIF(t1."客户群组" = 'SME', t2."消费量", 0)) AS REAL) / COUNT(t1."客户编号") AS _col_2 FROM "客户" AS t1 INNER JOIN "年月消费" AS t2 ON t1."客户编号" = t2."客户编号" WHERE t1."货币类型" = 'CZK' AND t2."消费量" = (SELECT MIN(yearmonth."消费量") AS _col_0 FROM "年月消费" AS yearmonth) AND t2."日期" BETWEEN 201301 AND 201312	debit_card_specializing
SELECT CAST((SUM(IIF(t1."客户群组" = 'SME' AND t2."日期" LIKE '2013%', t2."消费量", 0)) - SUM(IIF(t1."客户群组" = 'SME' AND t2."日期" LIKE '2012%', t2."消费量", 0))) AS REAL) * 100 / SUM(IIF(t1."客户群组" = 'SME' AND t2."日期" LIKE '2012%', t2."消费量", 0)) AS _col_0, CAST(SUM(IIF(t1."客户群组" = 'LAM' AND t2."日期" LIKE '2013%', t2."消费量", 0)) - SUM(IIF(t1."客户群组" = 'LAM' AND t2."日期" LIKE '2012%', t2."消费量", 0)) AS REAL) * 100 / SUM(IIF(t1."客户群组" = 'LAM' AND t2."日期" LIKE '2012%', t2."消费量", 0)) AS _col_1, CAST(SUM(IIF(t1."客户群组" = 'KAM' AND t2."日期" LIKE '2013%', t2."消费量", 0)) - SUM(IIF(t1."客户群组" = 'KAM' AND t2."日期" LIKE '2012%', t2."消费量", 0)) AS REAL) * 100 / SUM(IIF(t1."客户群组" = 'KAM' AND t2."日期" LIKE '2012%', t2."消费量", 0)) AS _col_2 FROM "客户" AS t1 INNER JOIN "年月消费" AS t2 ON t1."客户编号" = t2."客户编号"	debit_card_specializing
SELECT SUM(IIF(gasstations."国家" = 'CZE', 1, 0)) - SUM(IIF(gasstations."国家" = 'SVK', 1, 0)) AS _col_0 FROM "加油站" AS gasstations WHERE gasstations."业务分区" = 'Discount'	debit_card_specializing
SELECT CAST(SUM(IIF(yearmonth."消费量" > 528.3, 1, 0)) AS REAL) * 100 / COUNT(yearmonth."客户编号") AS _col_0 FROM "年月消费" AS yearmonth WHERE yearmonth."日期" = '201202'	debit_card_specializing
SELECT CAST(SUM(IIF(t2."货币类型" = 'EUR', 1, 0)) AS REAL) * 100 / COUNT(t1."客户编号") AS _col_0 FROM "交易记录" AS t1 INNER JOIN "客户" AS t2 ON t1."客户编号" = t2."客户编号" WHERE t1."交易日期" = '2012-08-25'	debit_card_specializing
SELECT CAST(SUM(IIF(gasstations."国家" = 'SVK' AND gasstations."业务分区" = 'Premium', 1, 0)) AS REAL) * 100 / SUM(IIF(gasstations."国家" = 'SVK', 1, 0)) AS _col_0 FROM "加油站" AS gasstations	debit_card_specializing
SELECT t2."金额" AS amount FROM "成员" AS t1 INNER JOIN "收入" AS t2 ON t1."成员编号" = t2."关联成员" WHERE t1."职位" = 'Vice President'	student_club
SELECT income."备注" AS notes FROM "收入" AS income WHERE income."来源" = 'Fundraising' AND income."收款日期" = '2019-09-14'	student_club
