SELECT COUNT(t1."成员编号") AS _col_0 FROM "成员" AS t1 INNER JOIN "专业" AS t2 ON t1."关联专业" = t2."专业编号" WHERE t2."专业名称" = 'Business' AND t1."T恤尺码" = 'Medium'	student_club
SELECT CAST(SUM(CASE WHEN t2."活动名称" = 'Yearly Kickoff' THEN t1."金额" ELSE 0 END) AS REAL) / SUM(CASE WHEN t2."活动名称" = 'October Meeting' THEN t1."金额" ELSE 0 END) AS _col_0 FROM "预算" AS t1 INNER JOIN "活动" AS t2 ON t1."关联活动" = t2."活动编号" WHERE t1."类别" = 'Advertisement' AND t2."类型" = 'Meeting'	student_club
SELECT SUM(expense."费用") AS _col_0 FROM "支出" AS expense WHERE expense."支出描述" = 'Pizza'	student_club
SELECT t1."名" AS first_name, t1."姓" AS last_name FROM "成员" AS t1 INNER JOIN "专业" AS t2 ON t1."关联专业" = t2."专业编号" WHERE t2."院系" = 'School of Applied Sciences, Technology and Education'	student_club
SELECT SUM(budget."已支出") AS _col_0 FROM "预算" AS budget WHERE budget."类别" = 'Food'	student_club
SELECT t2."名" AS first_name, t2."姓" AS last_name, t1."费用" AS cost FROM "支出" AS t1 INNER JOIN "成员" AS t2 ON t1."关联成员" = t2."成员编号" WHERE t1."支出描述" = 'Water, Veggie tray, supplies'	student_club
SELECT SUM(CASE WHEN patient."入院日期" = '+' THEN 1.0 ELSE 0 END) / SUM(CASE WHEN patient."入院日期" = '-' THEN 1 ELSE 0 END) AS _col_0 FROM "患者" AS patient WHERE patient."诊断" = 'SLE'	thrombosis_prediction
SELECT t1."检验日期" AS date, STRFTIME('%Y', t2."初诊日期") - STRFTIME('%Y', t2."出生日期") AS _col_1, t2."出生日期" AS birthday FROM "检验报告" AS t1 INNER JOIN "患者" AS t2 ON t1."编号" = t2."编号" WHERE t2."诊断" = 'SJS' AND NOT t2."出生日期" IS NULL ORDER BY t2."出生日期" ASC LIMIT 1	thrombosis_prediction
SELECT examination."抗心磷脂抗体IgA" AS "acl iga", examination."抗心磷脂抗体IgG" AS "acl igg", examination."抗心磷脂抗体IgM" AS "acl igm" FROM "检查记录" AS examination WHERE examination."编号" IN (SELECT patient."编号" AS id FROM "患者" AS patient WHERE patient."诊断" = 'SLE' AND patient."描述" = '1994-02-19') AND examination."检查日期" = '1993-11-12'	thrombosis_prediction
