SELECT t1."编号" AS id, t1."性别" AS sex FROM "患者" AS t1 INNER JOIN "检验报告" AS t2 ON t1."编号" = t2."编号" WHERE t1."诊断" = 'SLE' AND t2."血红蛋白" > 10 AND t2."血红蛋白" < 17 ORDER BY t1."出生日期" ASC LIMIT 1	thrombosis_prediction
