SELECT COUNT(t1."编号") AS _col_0 FROM "检查记录" AS t1 INNER JOIN "检验报告" AS t2 ON t1."编号" = t2."编号" WHERE t2."斯密斯抗体" IN ('negative', '0') AND t1."血栓形成" = 0	thrombosis_prediction
SELECT COUNT(DISTINCT t1."编号") AS _col_0 FROM "患者" AS t1 INNER JOIN "检验报告" AS t2 ON t1."编号" = t2."编号" INNER JOIN "检查记录" AS t3 ON t3."编号" = t2."编号" WHERE (t2."肝肾微粒体抗体" = 'negative' OR t2."肝肾微粒体抗体" = '0') AND t1."性别" = 'F' AND t3."症状" IS NULL	thrombosis_prediction
SELECT CAST(COUNT(CASE WHEN t2."惯用脚" = 'left' THEN t1."编号" ELSE NULL END) AS REAL) * 100 / COUNT(t1."编号") AS percent FROM "球员" AS t1 INNER JOIN "球员属性" AS t2 ON t1."球员API编号" = t2."球员API编号" WHERE SUBSTRING(t1."生日", 1, 4) BETWEEN '1987' AND '1992'	european_football_2
