SELECT DISTINCT t1."球队简称" AS team_short_name FROM "球队" AS t1 INNER JOIN "球队属性" AS t2 ON t1."球队API编号" = t2."球队API编号" WHERE t2."创造机会传球等级" = 'Safe'	european_football_2
