SELECT t2."语言" AS language FROM "系列" AS t1 INNER JOIN "系列翻译" AS t2 ON t1."代码" = t2."系列代码" WHERE t1."区块" = 'Ravnica' AND t1."基础系列大小" = 180	card_games
SELECT CAST(SUM(CASE WHEN t2."语言" = 'French' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(t1.id) AS _col_0 FROM "卡牌" AS t1 INNER JOIN "外文数据" AS t2 ON t1.UUID = t2.UUID WHERE t1."力量" IS NULL OR t1."力量" = '*'	card_games
SELECT COUNT(DISTINCT t1."编号") AS _col_0 FROM "系列" AS t1 INNER JOIN "系列翻译" AS t2 ON t2."系列代码" = t1."代码" WHERE t1."区块" = 'Ice Age' AND t2."语言" = 'Italian' AND NOT t2."翻译" IS NULL	card_games
SELECT CAST(COUNT(DISTINCT CASE WHEN t1."元素" = 'c' THEN t1."原子编号" ELSE NULL END) AS REAL) * 100 / COUNT(DISTINCT t1."原子编号") AS _col_0 FROM "原子" AS t1 INNER JOIN "化学键" AS t2 ON t1."分子编号" = t2."分子编号" WHERE t2."键类型" = '='	toxicology
SELECT COUNT(DISTINCT CASE WHEN t1."元素" = 'i' THEN t1."原子编号" ELSE NULL END) AS iodine_nums, COUNT(DISTINCT CASE WHEN t1."元素" = 's' THEN t1."原子编号" ELSE NULL END) AS sulfur_nums FROM "原子" AS t1 INNER JOIN "连接关系" AS t2 ON t1."原子编号" = t2."原子编号" INNER JOIN "化学键" AS t3 ON t2."化学键编号" = t3."化学键编号" WHERE t3."键类型" = '-'	toxicology
SELECT ROUND(CAST(COUNT(CASE WHEN t."元素" = 'h' THEN t."原子编号" ELSE NULL END) AS REAL) * 100 / COUNT(t."原子编号"), 4) AS _col_0 FROM "原子" AS t WHERE t."分子编号" = 'TR206'	toxicology
SELECT t2."化学键编号" AS bond_id FROM "原子" AS t1 INNER JOIN "连接关系" AS t2 ON t1."原子编号" = t2."原子编号" WHERE t2."化学键编号" IN (SELECT t3."化学键编号" AS bond_id FROM "连接关系" AS t3 INNER JOIN "原子" AS t4 ON t3."原子编号" = t4."原子编号" WHERE t4."元素" = 'p') AND t1."元素" = 'n'	toxicology
SELECT CAST(COUNT(t2."化学键编号") AS REAL) / COUNT(t1."原子编号") AS _col_0 FROM "原子" AS t1 INNER JOIN "连接关系" AS t2 ON t1."原子编号" = t2."原子编号" WHERE t1."元素" = 'i'	toxicology
SELECT DISTINCT t."元素" AS element FROM "原子" AS t WHERE NOT t."元素" IN (SELECT DISTINCT t1."元素" AS element FROM "原子" AS t1 INNER JOIN "连接关系" AS t2 ON t1."原子编号" = t2."原子编号")	toxicology
SELECT COUNT(t1."原子编号") AS _col_0 FROM "原子" AS t1 INNER JOIN "分子" AS t2 ON t1."分子编号" = t2."分子编号" INNER JOIN "化学键" AS t3 ON t2."分子编号" = t3."分子编号" WHERE t3."键类型" = '#' AND t1."元素" IN ('p', 'br')	toxicology
SELECT CAST(COUNT(CASE WHEN t1."元素" = 'cl' THEN t1."元素" ELSE NULL END) AS REAL) * 100 / COUNT(t1."元素") AS _col_0 FROM "原子" AS t1 INNER JOIN "分子" AS t2 ON t1."分子编号" = t2."分子编号" WHERE t2."标签" = '+'	toxicology
WITH subquery AS (SELECT DISTINCT t1."原子编号" AS atom_id, t1."元素" AS element, t1."分子编号" AS molecule_id, t2."标签" AS label FROM "原子" AS t1 INNER JOIN "分子" AS t2 ON t1."分子编号" = t2."分子编号" WHERE t2."分子编号" = 'TR006') SELECT CAST(COUNT(CASE WHEN subquery.element = 'h' THEN subquery.atom_id ELSE NULL END) AS REAL) / (CASE WHEN COUNT(subquery.atom_id) = 0 THEN NULL ELSE COUNT(subquery.atom_id) END) AS ratio, subquery.label AS label FROM subquery AS subquery GROUP BY subquery.label	toxicology
SELECT t2."CDS编号" AS cdscode FROM "学校" AS t1 INNER JOIN "免费及减价午餐计划" AS t2 ON t1."CDS编号" = t2."CDS编号" WHERE t2."K-12年级注册人数" + t2."5-17岁学生注册人数" > 500	california_schools
SELECT t1."学校名称" AS "school name", t2."街道" AS street, t2."城市" AS city, t2."州" AS state, t2."邮政编码" AS zip FROM "免费及减价午餐计划" AS t1 INNER JOIN "学校" AS t2 ON t1."CDS编号" = t2."CDS编号" WHERE t2."县" = 'Monterey' AND t1."5-17岁学生免费餐食人数" > 800 AND t1."学校类型" = 'High Schools (Public)'	california_schools
SELECT t2."学校" AS school, t2."DOC代码" AS doc FROM "免费及减价午餐计划" AS t1 INNER JOIN "学校" AS t2 ON t1."CDS编号" = t2."CDS编号" WHERE t2."资金类型" = 'Locally funded' AND (t1."K-12年级注册人数" - t1."5-17岁学生注册人数") > (SELECT AVG(t3."K-12年级注册人数" - t3."5-17岁学生注册人数") AS _col_0 FROM "免费及减价午餐计划" AS t3 INNER JOIN "学校" AS t4 ON t3."CDS编号" = t4."CDS编号" WHERE t4."资金类型" = 'Locally funded')	california_schools
SELECT CAST(t1."K-12年级免费及减价餐食（FRPM）人数" AS REAL) / t1."K-12年级注册人数" AS _col_0 FROM "免费及减价午餐计划" AS t1 INNER JOIN "学校" AS t2 ON t1."CDS编号" = t2."CDS编号" WHERE t2."SOC代码" = 66 ORDER BY t1."K-12年级免费及减价餐食（FRPM）人数" DESC LIMIT 5	california_schools
SELECT t2."学校" AS school, t1."写作平均分" AS avgscrwrite FROM "SAT成绩" AS t1 INNER JOIN "学校" AS t2 ON t1."CDS编号" = t2."CDS编号" WHERE t2."管理员1名" = 'Ricci' AND t2."管理员1姓" = 'Ulrich'	california_schools
SELECT CAST(SUM(CASE WHEN schools."DOC代码" = 54 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN schools."DOC代码" = 52 THEN 1 ELSE 0 END) AS _col_0 FROM "学校" AS schools WHERE schools."状态类型" = 'Merged' AND schools."县" = 'Orange'	california_schools
SELECT t2."学校" AS school, t1."5-17岁学生免费及减价餐食（FRPM）人数" * 100 / t1."5-17岁学生注册人数" AS _col_1 FROM "免费及减价午餐计划" AS t1 INNER JOIN "学校" AS t2 ON t1."CDS编号" = t2."CDS编号" WHERE t2."县" = 'Los Angeles' AND t2."服务年级范围" = 'K-9'	california_schools
SELECT t2."城市" AS city, COUNT(t2."CDS编号") AS _col_1 FROM "免费及减价午餐计划" AS t1 INNER JOIN "学校" AS t2 ON t1."CDS编号" = t2."CDS编号" WHERE t2."磁石学校（是/否）" = 1 AND t2."提供年级范围" = 'K-8' AND t1."国家学校午餐计划（NSLP）供餐资格状态" = 'Multiple Provision Types' GROUP BY t2."城市"	california_schools
SELECT COUNT(t1."客户编号") AS _col_0 FROM "客户" AS t1 INNER JOIN "行政区" AS t2 ON t1."行政区编号" = t2."行政区编号" WHERE t1."性别" = 'M' AND t2.A3 = 'north Bohemia' AND t2.A11 > 8000	financial
SELECT t1."账户编号" AS account_id FROM "账户" AS t1 INNER JOIN "授权关系" AS t2 ON t1."账户编号" = t2."账户编号" INNER JOIN "客户" AS t3 ON t2."客户编号" = t3."客户编号" INNER JOIN "行政区" AS t4 ON t4."行政区编号" = t1."行政区编号" WHERE t2."客户编号" = (SELECT client."客户编号" AS client_id FROM "客户" AS client ORDER BY client."出生日期" DESC LIMIT 1) GROUP BY t4.A11, t1."账户编号"	financial
SELECT COUNT(t2."客户编号") AS _col_0 FROM "行政区" AS t1 INNER JOIN "客户" AS t2 ON t1."行政区编号" = t2."行政区编号" WHERE t2."性别" = 'F' AND STRFTIME('%Y', t2."出生日期") < '1950' AND t1.A2 = 'Sokolov'	financial
SELECT t1."账户编号" AS account_id FROM "交易" AS t1 INNER JOIN "账户" AS t2 ON t1."账户编号" = t2."账户编号" WHERE STRFTIME('%Y', t1."交易日期") = '1998' AND t1."交易操作" = 'VYBER KARTOU' AND t1."交易金额" < (SELECT AVG(trans."交易金额") AS _col_0 FROM "交易" AS trans WHERE STRFTIME('%Y', trans."交易日期") = '1998')	financial
SELECT t4."交易编号" AS trans_id FROM "客户" AS t1 INNER JOIN "授权关系" AS t2 ON t1."客户编号" = t2."客户编号" INNER JOIN "账户" AS t3 ON t2."账户编号" = t3."账户编号" INNER JOIN "交易" AS t4 ON t3."账户编号" = t4."账户编号" WHERE t1."客户编号" = 3356 AND t4."交易操作" = 'VYBER'	financial
SELECT CAST(SUM(t1."性别" = 'M') AS REAL) * 100 / COUNT(t1."客户编号") AS _col_0 FROM "客户" AS t1 INNER JOIN "行政区" AS t3 ON t1."行政区编号" = t3."行政区编号" INNER JOIN "账户" AS t2 ON t2."行政区编号" = t3."行政区编号" INNER JOIN "授权关系" AS t4 ON t1."客户编号" = t4."客户编号" AND t2."账户编号" = t4."账户编号" WHERE t2."交易频率" = 'POPLATEK TYDNE'	financial
SELECT t1."客户编号" AS client_id, STRFTIME('%Y', CURRENT_TIMESTAMP) - STRFTIME('%Y', t3."出生日期") AS _col_1 FROM "授权关系" AS t1 INNER JOIN "银行卡" AS t2 ON t2."授权编号" = t1."授权编号" INNER JOIN "客户" AS t3 ON t1."客户编号" = t3."客户编号" WHERE t2."授权类型" = 'gold' AND t1."授权类型" = 'OWNER'	financial
SELECT t1."账户编号" AS account_id, t2.A2 AS a2, t2.A3 AS a3 FROM "账户" AS t1 INNER JOIN "行政区" AS t2 ON t1."行政区编号" = t2."行政区编号" WHERE t1."交易频率" = 'POPLATEK PO OBRATU' AND STRFTIME('%Y', t1."开户日期") = '1993'	financial
SELECT t1."账户编号" AS account_id, t1."交易频率" AS frequency FROM "账户" AS t1 INNER JOIN "行政区" AS t2 ON t1."行政区编号" = t2."行政区编号" WHERE t2.A3 = 'east Bohemia' AND STRFTIME('%Y', t1."开户日期") BETWEEN '1995' AND '2000'	financial
